// Android runner for the quality-accepted fixed-Alba, QNN-compatible Pocket route.
// The pinned Alba cache is the official fixed-voice state. Token IDs, deterministic
// noise, state ownership, EOS scanning, orchestration, and WAV encoding remain CPU work.
#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <memory>
#include <stdexcept>
#include <string>
#include <sys/resource.h>
#include <unordered_map>
#include <vector>
#include "onnxruntime_cxx_api.h"
namespace fs=std::filesystem;using Clock=std::chrono::steady_clock;
static double Now(){return std::chrono::duration<double>(Clock::now().time_since_epoch()).count();}static long Hwm(){struct rusage r{};return getrusage(RUSAGE_SELF,&r)?-1:r.ru_maxrss;}
static void P16(std::ostream&s,uint16_t x){char b[2]={char(x),char(x>>8)};s.write(b,2);}static void P32(std::ostream&s,uint32_t x){char b[4]={char(x),char(x>>8),char(x>>16),char(x>>24)};s.write(b,4);}
static std::vector<float> ReadFloats(const fs::path&p,size_t count){std::ifstream s(p,std::ios::binary|std::ios::ate);if(!s||size_t(s.tellg())!=count*4)throw std::runtime_error("float fixture size: "+p.string());s.seekg(0);std::vector<float>x(count);s.read(reinterpret_cast<char*>(x.data()),count*4);if(!s)throw std::runtime_error("float fixture read");return x;}
static void WriteWav(const fs::path&p,const std::vector<float>&v){std::ofstream s(p,std::ios::binary|std::ios::trunc);uint32_t n=v.size()*2;s.write("RIFF",4);P32(s,36+n);s.write("WAVEfmt ",8);P32(s,16);P16(s,1);P16(s,1);P32(s,24000);P32(s,48000);P16(s,2);P16(s,16);s.write("data",4);P32(s,n);for(float x:v){long q=long(std::nearbyint(std::clamp(x,-1.f,1.f)*32767.f));P16(s,uint16_t(int16_t(std::clamp(q,-32768L,32767L))));}if(!s)throw std::runtime_error("wav write");}
struct Model{std::string name,prefix;std::unique_ptr<Ort::Session>s;std::vector<std::string>in,out;std::vector<const char*>ip,op;double create_s=0;};
static Ort::SessionOptions Options(const std::string&backend,const std::string&prefix,bool profile){Ort::SessionOptions o;o.SetIntraOpNumThreads(1);o.SetInterOpNumThreads(1);o.SetExecutionMode(ExecutionMode::ORT_SEQUENTIAL);o.SetGraphOptimizationLevel(backend=="cpu"?GraphOptimizationLevel::ORT_ENABLE_ALL:GraphOptimizationLevel::ORT_ENABLE_BASIC);if(profile)o.EnableProfiling(prefix.c_str());if(backend!="cpu"){o.AddConfigEntry("session.disable_cpu_ep_fallback","1");std::unordered_map<std::string,std::string>q={{"backend_path",backend},{"offload_graph_io_quantization","0"},{"htp_performance_mode","burst"},{"soc_model","43"},{"enable_htp_fp16_precision","0"}};if(profile){q["profiling_level"]="detailed";q["profiling_file_path"]=prefix+".qnn.csv";}o.AppendExecutionProvider("QNN",q);}return o;}
static Model Load(Ort::Env&e,const fs::path&p,const std::string&name,const fs::path&profiles,const std::string&backend,bool profile){Model m;m.name=name;m.prefix=(profiles/name).string();auto o=Options(backend,m.prefix,profile);double t=Now();m.s=std::make_unique<Ort::Session>(e,p.c_str(),o);m.create_s=Now()-t;Ort::AllocatorWithDefaultOptions a;for(size_t i=0;i<m.s->GetInputCount();++i){auto x=m.s->GetInputNameAllocated(i,a);m.in.emplace_back(x.get());}for(size_t i=0;i<m.s->GetOutputCount();++i){auto x=m.s->GetOutputNameAllocated(i,a);m.out.emplace_back(x.get());}for(auto&x:m.in)m.ip.push_back(x.c_str());for(auto&x:m.out)m.op.push_back(x.c_str());return m;}
static std::vector<Ort::Value> Run(Model&m,std::vector<Ort::Value>&v){if(v.size()!=m.ip.size())throw std::runtime_error(m.name+" input count");return m.s->Run(Ort::RunOptions{nullptr},m.ip.data(),v.data(),v.size(),m.op.data(),m.op.size());}
template<class T>static Ort::Value TV(Ort::MemoryInfo&mi,std::vector<T>&v,std::initializer_list<int64_t>shape){std::vector<int64_t>s(shape);return Ort::Value::CreateTensor<T>(mi,v.data(),v.size(),s.data(),s.size());}static std::vector<float> CopyFloat(Ort::Value&v){auto i=v.GetTensorTypeAndShapeInfo();auto*p=v.GetTensorData<float>();return {p,p+i.GetElementCount()};}
static std::vector<Ort::Value> InitFixedState(const std::vector<float>&packed,Ort::AllocatorWithDefaultOptions&a){constexpr size_t H=16,D=64,SRC=126,CAP=256,PER=2*SRC*H*D;if(packed.size()!=6*PER)throw std::runtime_error("Alba cache pack");std::vector<Ort::Value>x;x.reserve(13);std::array<int64_t,4>shape{1,H,CAP,D};for(size_t layer=0;layer<6;++layer)for(size_t kv=0;kv<2;++kv){auto v=Ort::Value::CreateTensor<float>(a,shape.data(),shape.size());float*dst=v.GetTensorMutableData<float>();std::fill(dst,dst+H*CAP*D,0.f);const float*src=packed.data()+layer*PER+kv*SRC*H*D;for(size_t pos=0;pos<SRC;++pos)for(size_t head=0;head<H;++head)std::copy(src+(pos*H+head)*D,src+(pos*H+head+1)*D,dst+(head*CAP+(CAP-SRC+pos))*D);x.push_back(std::move(v));}std::array<int64_t,4>mshape{1,1,1,CAP};auto mask=Ort::Value::CreateTensor<float>(a,mshape.data(),mshape.size());float*mp=mask.GetTensorMutableData<float>();std::fill(mp,mp+CAP,-10000.f);std::fill(mp+CAP-SRC,mp+CAP,0.f);x.push_back(std::move(mask));return x;}
static std::vector<Ort::Value> StaticCall(Model&m,Ort::Value*lead,std::vector<int64_t>&positions,std::vector<Ort::Value>&state,Ort::MemoryInfo&mi){std::vector<Ort::Value>v;if(lead)v.push_back(std::move(*lead));v.push_back(TV(mi,positions,{int64_t(positions.size())}));v.push_back(std::move(state[12]));for(int i=0;i<12;++i)v.push_back(std::move(state[i]));auto result=Run(m,v);size_t offset=m.name=="prefill_text"?0:2;state.clear();for(size_t i=0;i<13;++i)state.push_back(std::move(result[offset+i]));return result;}
static std::vector<Ort::Value> InitDecoder(Model&m,Ort::AllocatorWithDefaultOptions&a){std::vector<Ort::Value>x;for(size_t i=1;i<m.in.size();++i){auto info=m.s->GetInputTypeInfo(i).GetTensorTypeAndShapeInfo();auto sh=info.GetShape();auto ty=info.GetElementType();auto v=Ort::Value::CreateTensor(a,sh.data(),sh.size(),ty);size_t n=info.GetElementCount();if(ty==ONNX_TENSOR_ELEMENT_DATA_TYPE_FLOAT)std::fill(v.GetTensorMutableData<float>(),v.GetTensorMutableData<float>()+n,0.f);else if(ty==ONNX_TENSOR_ELEMENT_DATA_TYPE_INT64)std::fill(v.GetTensorMutableData<int64_t>(),v.GetTensorMutableData<int64_t>()+n,0);else if(ty==ONNX_TENSOR_ELEMENT_DATA_TYPE_BOOL)memset(v.GetTensorMutableRawData(),1,n);else throw std::runtime_error("decoder state dtype");x.push_back(std::move(v));}if(x.size()!=56)throw std::runtime_error("decoder state ABI");return x;}
int main(int argc,char**argv){try{if(argc!=10)throw std::runtime_error("usage: runner MODEL_DIR ALBA_CACHE NOISE_F32 OUTPUT_WAV PROFILE_DIR|- BACKEND|cpu TEMPERATURE MAX_FRAMES VARIANT");fs::path root=argv[1],cache_path=argv[2],noise_path=argv[3],wav=argv[4],profiles=argv[5];std::string backend=argv[6],variant=argv[9];float temperature=std::stof(argv[7]);int max_frames=std::stoi(argv[8]);bool profile=profiles!="-";if(profile)fs::create_directories(profiles);if((temperature!=0.3f&&temperature!=0.7f)||max_frames<1||max_frames>100)throw std::runtime_error("contract range; 256 slots preserve all 126 voice + 26 text + at most 100 generated positions");auto packed=ReadFloats(cache_path,6*2*126*16*64);auto noise=ReadFloats(noise_path,134*32);Ort::Env env(ORT_LOGGING_LEVEL_WARNING,"pocket-alba-static");double l0=Now();std::vector<Model>models;models.reserve(8);auto L=[&](const char*file,const char*name)->Model&{std::cerr<<"loading "<<name<<" hwm_kb="<<Hwm()<<"\n"<<std::flush;models.push_back(Load(env,root/file,name,profiles,backend,profile));std::cerr<<"loaded "<<name<<" seconds="<<models.back().create_s<<" hwm_kb="<<Hwm()<<"\n"<<std::flush;return models.back();};Model&text=L("text_conditioner.onnx","text");Model&prefill=L("flow_prefill_text26.onnx","prefill_text");Model&bos=L("flow_ar_bos1.onnx","ar_bos");Model&ar=L("flow_ar_latent1.onnx","ar_latent");Model&flow=L("flow.onnx","flow");Model&d12=L("mimi_decoder12.onnx","decoder12");Model&d6=L("mimi_decoder6.onnx","decoder6");Model&d1=L("mimi_decoder1.onnx","decoder1");double load=Now()-l0;Ort::MemoryInfo mi=Ort::MemoryInfo::CreateCpu(OrtArenaAllocator,OrtMemTypeDefault);Ort::AllocatorWithDefaultOptions alloc;double g0=Now(),tt=0,tp=0,ta=0,tf=0,td=0;
 std::vector<int64_t>ids={1456,603,597,602,854,640,791,261,260,1332,323,288,285,287,489,594,1355,1049,265,311,2081,3697,273,519,1836,263};std::vector<Ort::Value>ti;ti.push_back(TV(mi,ids,{1,26}));double t=Now();auto tr=Run(text,ti);tt+=Now()-t;auto text_embedding=CopyFloat(tr[0]);auto state=InitFixedState(packed,alloc);std::vector<int64_t>positions(26);for(int i=0;i<26;++i)positions[i]=126+i;auto text_value=TV(mi,text_embedding,{1,26,1024});t=Now();StaticCall(prefill,&text_value,positions,state,mi);tp+=Now()-t;
 std::vector<float>current(32),latents,logits;int eos=-1;std::vector<float>s0{0.f},t1{1.f};for(int step=0;step<max_frames;++step){positions={152+step};t=Now();std::vector<Ort::Value>result;if(step==0)result=StaticCall(bos,nullptr,positions,state,mi);else{auto cv=TV(mi,current,{1,1,32});result=StaticCall(ar,&cv,positions,state,mi);}ta+=Now()-t;float logit=result[1].GetTensorData<float>()[0];logits.push_back(logit);if(eos<0&&logit>-4.f)eos=step;if(eos>=0&&step>=eos+3)break;std::vector<float>step_noise(noise.begin()+step*32,noise.begin()+(step+1)*32);std::vector<Ort::Value>fi;fi.push_back(std::move(result[0]));fi.push_back(TV(mi,s0,{1,1}));fi.push_back(TV(mi,t1,{1,1}));fi.push_back(TV(mi,step_noise,{1,32}));t=Now();auto fr=Run(flow,fi);tf+=Now()-t;const float*direction=fr[0].GetTensorData<float>();for(int i=0;i<32;++i)current[i]=step_noise[i]+direction[i];latents.insert(latents.end(),current.begin(),current.end());}
 int frames=int(latents.size()/32);if(!frames)throw std::runtime_error("no latents");auto decoder_state=InitDecoder(d12,alloc);std::vector<float>audio;int start=0;auto Decode=[&](Model&m,int n){std::vector<float>chunk(latents.begin()+start*32,latents.begin()+(start+n)*32);std::vector<Ort::Value>inputs;inputs.push_back(TV(mi,chunk,{1,n,32}));for(auto&x:decoder_state)inputs.push_back(std::move(x));double q=Now();auto result=Run(m,inputs);td+=Now()-q;auto y=CopyFloat(result[0]);audio.insert(audio.end(),y.begin(),y.end());decoder_state.clear();for(int i=0;i<56;++i)decoder_state.push_back(std::move(result[1+i]));start+=n;};while(start<frames){int remaining=frames-start;if(remaining>=12)Decode(d12,12);else if(remaining==6)Decode(d6,6);else Decode(d1,1);}if(int(audio.size())!=frames*1920)throw std::runtime_error("audio length");WriteWav(wav,audio);double generation=Now()-g0;std::vector<std::string>profile_paths;if(profile)for(auto&m:models){auto p=m.s->EndProfilingAllocated(alloc);profile_paths.emplace_back(p.get());}
 std::cout<<"{\"route\":\""<<(backend=="cpu"?"fixed_alba_android_cpu":"fixed_alba_fallback_disabled_qnn")<<"\",\"variant\":\""<<variant<<"\",\"provider\":\""<<(backend=="cpu"?"CPUExecutionProvider":"QNNExecutionProvider")<<"\",\"cpu_fallback\":"<<(backend=="cpu"?"null":"false")<<",\"graph_optimization\":\""<<(backend=="cpu"?"all":"basic")<<"\",\"temperature\":"<<temperature<<",\"seed\":0,\"noise_fixture\":\"NumPy RandomState MT19937 normal\",\"max_frames\":"<<max_frames<<",\"load_seconds\":"<<load<<",\"generation_seconds\":"<<generation<<",\"component_seconds\":{\"text\":"<<tt<<",\"prefill\":"<<tp<<",\"ar\":"<<ta<<",\"flow\":"<<tf<<",\"decoder\":"<<td<<"},\"eos_step\":"<<eos<<",\"latent_frames\":"<<frames<<",\"samples\":"<<audio.size()<<",\"audio_seconds\":"<<audio.size()/24000.0<<",\"rtf\":"<<generation/(audio.size()/24000.0)<<",\"vm_hwm_kb\":"<<Hwm()<<",\"ort_profiles\":[";for(size_t i=0;i<profile_paths.size();++i){if(i)std::cout<<",";std::cout<<"\""<<profile_paths[i]<<"\"";}std::cout<<"],\"eos_logits\":[";for(size_t i=0;i<logits.size();++i){if(i)std::cout<<",";std::cout<<logits[i];}std::cout<<"]}\n";return 0;}catch(const Ort::Exception&e){std::cerr<<"ORT "<<e.GetOrtErrorCode()<<": "<<e.what()<<"\n";return 2;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<"\n";return 3;}}
